/**
 * The output renditions and transformations that should be generated from the source file.
 */
export type OutputsOutputs = {
    /**
     * The output renditions and transformations that should be generated from the source file.
     */
    renditions?: Array<RenditionRendition>;
    transcription?: TranscriptionTranscription;
};

/**
 * A rendition is a new output file that is generated from the source. The rendition can be encoded to a different format and have transformations applied to it such as resizing, cropping, etc...
 */
export type RenditionRendition = {
    /**
     * The output format to encode the file to. You can only encode a file to the same type, i.e. a video to a video or an image to an image. You can't encode a video as an image. The following formats are available: <ul>
     * <li>`mp4` - mp4 video file (video only)</li>
     * <li>`webm` - webm video file (video only)</li>
     * <li>`mov` - mov video file (video only)</li>
     * <li>`avi` - avi video file (video only)</li>
     * <li>`mkv` - mkv video file (video only)</li>
     * <li>`ogv` - ogv video file (video only)</li>
     * <li>`wmv` - wmv video file (video only)</li>
     * <li>`avif` - avif video file (video only)</li>
     * <li>`gif` - animated gif file (video only)</li>
     * <li>`jpg` - jpg image file (image only)</li>
     * <li>`png` - png image file (image only)</li>
     * <li>`webp` - webp image file (image only)</li>
     * <li>`tif` - tif image file (image only)</li>
     * <li>`mp3` - mp3 audio file (audio only)</li>
     * <li>`wav` - wav audio file (audio only)</li>
     * </ul>
     */
    format?: 'mp4' | 'webm' | 'mov' | 'avi' | 'mkv' | 'ogv' | 'wmv' | 'avif' | 'gif' | 'mp3' | 'wav' | 'jpg' | 'png' | 'webp' | 'tif';
    size?: SizeSize;
    /**
     * Set how the rendition should be scaled and cropped when using a size with an aspect ratio that is different from the source. Fit applies to both videos and images. <ul>
     * <li>`crop` <b>(default)</b> - scale the rendition to fill the output area while maintaining the aspect ratio. The rendition will be cropped if it exceeds the bounds of the output.</li>
     * <li>`cover` - stretch the rendition to fill the output without maintaining the aspect ratio.</li>
     * <li>`contain` - fit the entire rendition within the output while maintaining the original aspect ratio.</li>
     * </ul>
     */
    fit?: 'cover' | 'contain' | 'crop';
    /**
     * The preset output resolution of the video or image. This is a convenience property that sets the width and height based on industry standard resolutions. The following resolutions are available: <ul>
     * <li>`preview` - 512px x 288px</li>
     * <li>`mobile` - 640px x 360px</li>
     * <li>`sd` - 1024px x 576px</li>
     * <li>`hd` - 1280px x 720px</li>
     * <li>`fhd` - 1920px x 1080px</li>
     * </ul>
     */
    resolution?: 'preview' | 'mobile' | 'sd' | 'hd' | 'fhd';
    /**
     * Adjust the visual quality of the video or image. The higher the value, the sharper the image quality but the larger file size and slower the encoding process. When specifying quality, the goal is to balance file size vs visual quality.
     * Quality is a value between 1 and 100 where 1 is fully compressed with low image quality and 100 is close to lossless with high image quality and large file size. Sane values are between 50 and 75. Omitting the quality parameter will result in an asset optimised for encoding speed, file size and visual quality.
     */
    quality?: number;
    /**
     * Change the frame rate of a video asset. <ul>
     * <li>`12` - 12fps</li>
     * <li>`15` - 15fps</li>
     * <li>`24` - 24fps</li>
     * <li>`23.976` - 23.976fps</li>
     * <li>`25` (default) - 25fps</li>
     * <li>`29.97` - 29.97fps</li>
     * <li>`30` - 30fps</li>
     * <li>`48` - 48fps</li>
     * <li>`50` - 50fps</li>
     * <li>`59.94` - 59.94fps</li>
     * <li>`60` - 60fps</li>
     * </ul>
     */
    fps?: 12 | 15 | 23.976 | 24 | 25 | 29.97 | 30 | 48 | 50 | 59.94 | 60;
    speed?: SpeedSpeed;
    /**
     * The keyframe interval is useful to optimize playback, seeking and smoother scrubbing in browsers. The value sets the number of frames between a keyframe. The lower the number, the larger the file. Try a value between 10 and 25 for smooth scrubbing.
     */
    keyframeInterval?: number;
    /**
     * Attempt to fix audio and video sync issues. This can occur when recording devices, such as smartphones and
     * web cams use compression techniques like [Variable Frame Rate](https://en.wikipedia.org/wiki/Variable_frame_rate)
     * (VFR) which can cause audio and video to go out of sync. This option will attempt to fix the sync issues.
     */
    fixOffset?: boolean;
    /**
     * Automatically reset the rotation of the video based on the orientation metadata in the video file. This is useful for videos recorded on smartphones that have orientation metadata that may not work correctly with certain video editing software, including the Shotstack Edit API.
     */
    fixRotation?: boolean;
    enhance?: EnhancementsEnhancements;
    /**
     * A custom name for the generated rendition file. The file extension will be automatically added based on the format of the rendition. If no filename is provided, the rendition ID will be used.
     */
    filename?: string;
};

